mapper.select:
SELECT DISTINCT u.id, u.username, u.real_name AS realName, u.avatar, u.gender, u.student_no AS studentNo, u.phone, u.email, u.status, u.register_time AS registerTime, u.create_time AS createTime, u.update_time AS updateTime FROM t_s_user u
INNER JOIN t_s_user_group_member ugm ON ugm.user_id = u.id AND ugm.deleted = 0 AND ugm.user_group_id = #{q.userGroupId}
INNER JOIN t_s_user_role ur ON ur.user_id = u.id AND ur.deleted = 0 AND ur.role_id = #{q.roleId}
WHERE u.deleted = 0
AND u.username LIKE CONCAT('%', #{q.username}, '%')
AND u.real_name LIKE CONCAT('%', #{q.realName}, '%')
AND u.status = #{q.status}
ORDER BY u.id DESC
